package cli

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestReadLastNLines_ShortInput(t *testing.T) {
	t.Parallel()

	r := strings.NewReader("a\nb\nc\n")
	got, err := readLastNLines(r, 5)
	if err != nil {
		t.Fatalf("readLastNLines: %v", err)
	}
	want := []string{"a\n", "b\n", "c\n"}
	if len(got) != len(want) {
		t.Fatalf("got %d lines, want %d (%v)", len(got), len(want), got)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("line %d = %q, want %q", i, got[i], want[i])
		}
	}
}

func TestReadLastNLines_LongInputTruncated(t *testing.T) {
	t.Parallel()

	r := strings.NewReader("a\nb\nc\nd\ne\nf\n")
	got, err := readLastNLines(r, 3)
	if err != nil {
		t.Fatalf("readLastNLines: %v", err)
	}
	want := []string{"d\n", "e\n", "f\n"}
	if len(got) != len(want) {
		t.Fatalf("got %d lines, want %d (%v)", len(got), len(want), got)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("line %d = %q, want %q", i, got[i], want[i])
		}
	}
}

func TestPrintTail_ZeroNCopiesAll(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	path := filepath.Join(dir, "log.txt")
	contents := "alpha\nbeta\ngamma\n"
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatalf("write log: %v", err)
	}

	var buf bytes.Buffer
	if err := printTail(&buf, path, 0); err != nil {
		t.Fatalf("printTail: %v", err)
	}
	if buf.String() != contents {
		t.Errorf("printTail copy = %q, want %q", buf.String(), contents)
	}
}

func TestPrintTail_TailsLastN(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	path := filepath.Join(dir, "log.txt")
	contents := "1\n2\n3\n4\n5\n"
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatalf("write log: %v", err)
	}

	var buf bytes.Buffer
	if err := printTail(&buf, path, 2); err != nil {
		t.Fatalf("printTail: %v", err)
	}
	if buf.String() != "4\n5\n" {
		t.Errorf("printTail tail = %q, want \"4\\n5\\n\"", buf.String())
	}
}

package cli

import (
	"bytes"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

func TestComputeCheckpointDiff_FilesAddedAndRemoved(t *testing.T) {
	t.Parallel()

	a := &checkpoint.CheckpointSummary{
		CheckpointID:     id.MustCheckpointID("aaaaaaaaaaaa"),
		FilesTouched:     []string{"src/a.go", "src/b.go"},
		CheckpointsCount: 1,
	}
	b := &checkpoint.CheckpointSummary{
		CheckpointID:     id.MustCheckpointID("bbbbbbbbbbbb"),
		FilesTouched:     []string{"src/b.go", "src/c.go"},
		CheckpointsCount: 2,
	}

	d := computeCheckpointDiff(a, b)

	if got, want := d.FilesAdded, []string{"src/c.go"}; !equalStringSlices(got, want) {
		t.Errorf("FilesAdded = %v, want %v", got, want)
	}
	if got, want := d.FilesRemoved, []string{"src/a.go"}; !equalStringSlices(got, want) {
		t.Errorf("FilesRemoved = %v, want %v", got, want)
	}
	if d.SessionsDelta != 1 {
		t.Errorf("SessionsDelta = %d, want 1", d.SessionsDelta)
	}
}

func TestComputeCheckpointDiff_TokenDelta(t *testing.T) {
	t.Parallel()

	a := &checkpoint.CheckpointSummary{
		CheckpointID: id.MustCheckpointID("aaaaaaaaaaaa"),
		TokenUsage: &agent.TokenUsage{
			InputTokens:         100,
			OutputTokens:        50,
			CacheReadTokens:     200,
			CacheCreationTokens: 25,
		},
	}
	b := &checkpoint.CheckpointSummary{
		CheckpointID: id.MustCheckpointID("bbbbbbbbbbbb"),
		TokenUsage: &agent.TokenUsage{
			InputTokens:         150,
			OutputTokens:        100,
			CacheReadTokens:     300,
			CacheCreationTokens: 50,
		},
	}

	d := computeCheckpointDiff(a, b)

	if d.TokensDelta.Input != 50 {
		t.Errorf("Input delta = %d, want 50", d.TokensDelta.Input)
	}
	if d.TokensDelta.Output != 50 {
		t.Errorf("Output delta = %d, want 50", d.TokensDelta.Output)
	}
	if d.TokensDelta.CacheRead != 100 {
		t.Errorf("CacheRead delta = %d, want 100", d.TokensDelta.CacheRead)
	}
	if d.TokensDelta.CacheWrite != 25 {
		t.Errorf("CacheWrite delta = %d, want 25", d.TokensDelta.CacheWrite)
	}
	if d.TokensDelta.Total != 225 {
		t.Errorf("Total delta = %d, want 225", d.TokensDelta.Total)
	}
}

func TestComputeCheckpointDiff_IdenticalInputsHaveEmptyDiff(t *testing.T) {
	t.Parallel()

	a := &checkpoint.CheckpointSummary{
		CheckpointID:     id.MustCheckpointID("aaaaaaaaaaaa"),
		FilesTouched:     []string{"x.go", "y.go"},
		CheckpointsCount: 3,
	}
	b := &checkpoint.CheckpointSummary{
		CheckpointID:     id.MustCheckpointID("bbbbbbbbbbbb"),
		FilesTouched:     []string{"y.go", "x.go"}, // order intentionally different
		CheckpointsCount: 3,
	}

	d := computeCheckpointDiff(a, b)

	if len(d.FilesAdded) != 0 {
		t.Errorf("FilesAdded = %v, want empty", d.FilesAdded)
	}
	if len(d.FilesRemoved) != 0 {
		t.Errorf("FilesRemoved = %v, want empty", d.FilesRemoved)
	}
	if d.SessionsDelta != 0 {
		t.Errorf("SessionsDelta = %d, want 0", d.SessionsDelta)
	}
}

func TestComputeCheckpointDiff_NilTokenUsageHandled(t *testing.T) {
	t.Parallel()

	a := &checkpoint.CheckpointSummary{CheckpointID: id.MustCheckpointID("aaaaaaaaaaaa")}
	b := &checkpoint.CheckpointSummary{
		CheckpointID: id.MustCheckpointID("bbbbbbbbbbbb"),
		TokenUsage:   &agent.TokenUsage{InputTokens: 10, OutputTokens: 20},
	}

	d := computeCheckpointDiff(a, b)

	if d.TokensDelta.Input != 10 || d.TokensDelta.Output != 20 || d.TokensDelta.Total != 30 {
		t.Errorf("token delta from nil-A: %+v", d.TokensDelta)
	}
}

func TestWriteCheckpointDiffText_RendersIdenticalSet(t *testing.T) {
	t.Parallel()

	a := &checkpoint.CheckpointSummary{
		CheckpointID: id.MustCheckpointID("aaaaaaaaaaaa"),
		FilesTouched: []string{"a"},
	}
	b := &checkpoint.CheckpointSummary{
		CheckpointID: id.MustCheckpointID("bbbbbbbbbbbb"),
		FilesTouched: []string{"a"},
	}
	d := computeCheckpointDiff(a, b)

	var buf bytes.Buffer
	if err := writeCheckpointDiffText(&buf, d); err != nil {
		t.Fatalf("writeCheckpointDiffText: %v", err)
	}
	if !strings.Contains(buf.String(), "identical set") {
		t.Errorf("expected 'identical set' phrase, got:\n%s", buf.String())
	}
}

func equalStringSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

package cli

import (
	"archive/zip"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/spf13/cobra"
)

func newDoctorBundleCmd() *cobra.Command {
	var outFlag string

	cmd := &cobra.Command{
		Use:   "bundle",
		Short: "Produce a diagnostic bundle (zip) for bug reports",
		Long: `Produce a zip archive containing logs, settings, and a git snapshot suitable
for attaching to bug reports.

The archive includes:
  - .entire/logs/  (operational logs)
  - .entire/settings.json and settings.local.json (if present)
  - git-status.txt, git-log.txt, git-remote.txt
  - version.txt with CLI version, Go version, OS/Arch

By default the archive is written to a path inside the OS temp directory and
that path is printed to stdout. Use --out to choose a specific path.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			repoRoot, err := paths.WorktreeRoot(ctx)
			if err != nil {
				cmd.SilenceUsage = true
				return errors.New("not a git repository")
			}

			outPath := outFlag
			if outPath == "" {
				outPath = filepath.Join(os.TempDir(), fmt.Sprintf("entire-bundle-%s.zip", time.Now().UTC().Format("20060102-150405")))
			}

			if err := writeDoctorBundle(ctx, repoRoot, outPath); err != nil {
				return err
			}

			fmt.Fprintln(cmd.OutOrStdout(), outPath)
			return nil
		},
	}

	cmd.Flags().StringVarP(&outFlag, "out", "o", "", "Path to write the bundle archive (default: OS temp dir)")
	return cmd
}

func writeDoctorBundle(ctx context.Context, repoRoot, outPath string) error {
	out, err := os.Create(outPath) //nolint:gosec // user-provided output path is intentional
	if err != nil {
		return fmt.Errorf("create bundle: %w", err)
	}
	defer out.Close()

	zw := zip.NewWriter(out)
	defer zw.Close()

	logsDir := filepath.Join(repoRoot, logging.LogsDir)
	if err := addDirToZip(zw, logsDir, "logs"); err != nil {
		return err
	}

	for _, name := range []string{"settings.json", "settings.local.json"} {
		src := filepath.Join(repoRoot, ".entire", name)
		if err := addFileToZip(zw, src, filepath.Join("settings", name)); err != nil {
			return err
		}
	}

	if err := addCommandOutput(ctx, zw, "git-status.txt", repoRoot, "git", "status", "--short", "--branch"); err != nil {
		return err
	}
	if err := addCommandOutput(ctx, zw, "git-log.txt", repoRoot, "git", "log", "-n", "50", "--oneline"); err != nil {
		return err
	}
	if err := addCommandOutput(ctx, zw, "git-remote.txt", repoRoot, "git", "remote", "-v"); err != nil {
		return err
	}

	if err := addStringToZip(zw, "version.txt", versionInfoString()); err != nil {
		return err
	}

	return nil
}

func versionInfoString() string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "Entire CLI %s (%s)\n", versioninfo.Version, versioninfo.Commit)
	fmt.Fprintf(&sb, "Go: %s\n", runtime.Version())
	fmt.Fprintf(&sb, "OS/Arch: %s/%s\n", runtime.GOOS, runtime.GOARCH)
	return sb.String()
}

func addDirToZip(zw *zip.Writer, srcDir, archivePrefix string) error {
	info, err := os.Stat(srcDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("stat %s: %w", srcDir, err)
	}
	if !info.IsDir() {
		return nil
	}
	walkErr := filepath.Walk(srcDir, func(path string, fi os.FileInfo, werr error) error {
		if werr != nil {
			return werr
		}
		if fi.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(srcDir, path)
		if err != nil {
			return fmt.Errorf("rel: %w", err)
		}
		return addFileToZip(zw, path, filepath.Join(archivePrefix, rel))
	})
	if walkErr != nil {
		return fmt.Errorf("walk %s: %w", srcDir, walkErr)
	}
	return nil
}

func addFileToZip(zw *zip.Writer, src, archivePath string) error {
	f, err := os.Open(src) //nolint:gosec // path comes from repo-internal walk
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("open %s: %w", src, err)
	}
	defer f.Close()

	w, err := zw.Create(archivePath)
	if err != nil {
		return fmt.Errorf("zip create %s: %w", archivePath, err)
	}
	if _, err := io.Copy(w, f); err != nil {
		return fmt.Errorf("zip copy %s: %w", archivePath, err)
	}
	return nil
}

func addStringToZip(zw *zip.Writer, archivePath, contents string) error {
	w, err := zw.Create(archivePath)
	if err != nil {
		return fmt.Errorf("zip create %s: %w", archivePath, err)
	}
	if _, err := io.WriteString(w, contents); err != nil {
		return fmt.Errorf("zip write %s: %w", archivePath, err)
	}
	return nil
}

func addCommandOutput(ctx context.Context, zw *zip.Writer, archivePath, dir, name string, args ...string) error {
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		out = append(out, []byte(fmt.Sprintf("\n[error: %v]\n", err))...)
	}
	return addStringToZip(zw, archivePath, string(out))
}

package cli

import (
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/spf13/cobra"
)

func newCheckpointDiffCmd() *cobra.Command {
	var jsonFlag bool

	cmd := &cobra.Command{
		Use:   "diff <checkpoint-a> <checkpoint-b>",
		Short: "Compare two checkpoints",
		Long: `Compare two checkpoints by ID and report the delta in files touched,
token usage, and session counts.

Both arguments must be full 12-character hex checkpoint IDs.

Examples:
  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6
  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6 --json`,
		Args: cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()

			aID, err := id.NewCheckpointID(args[0])
			if err != nil {
				return fmt.Errorf("invalid checkpoint A: %w", err)
			}
			bID, err := id.NewCheckpointID(args[1])
			if err != nil {
				return fmt.Errorf("invalid checkpoint B: %w", err)
			}

			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				return fmt.Errorf("open repository: %w", err)
			}
			store := checkpoint.NewGitStore(repo)

			a, err := store.ReadCommitted(ctx, aID)
			if err != nil {
				return fmt.Errorf("read checkpoint %s: %w", aID, err)
			}
			b, err := store.ReadCommitted(ctx, bID)
			if err != nil {
				return fmt.Errorf("read checkpoint %s: %w", bID, err)
			}

			d := computeCheckpointDiff(a, b)
			if jsonFlag {
				return writeCheckpointDiffJSON(cmd.OutOrStdout(), d)
			}
			return writeCheckpointDiffText(cmd.OutOrStdout(), d)
		},
	}

	cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
	return cmd
}

type checkpointDiff struct {
	A             *checkpoint.CheckpointSummary `json:"-"`
	B             *checkpoint.CheckpointSummary `json:"-"`
	AID           string                        `json:"a"`
	BID           string                        `json:"b"`
	ASessions     int                           `json:"a_sessions"`
	BSessions     int                           `json:"b_sessions"`
	SessionsDelta int                           `json:"sessions_delta"`
	FilesAdded    []string                      `json:"files_added"`
	FilesRemoved  []string                      `json:"files_removed"`
	TokensDelta   tokenDelta                    `json:"tokens_delta"`
}

type tokenDelta struct {
	Total      int `json:"total"`
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cache_read"`
	CacheWrite int `json:"cache_write"`
}

func computeCheckpointDiff(a, b *checkpoint.CheckpointSummary) *checkpointDiff {
	out := &checkpointDiff{
		A:             a,
		B:             b,
		AID:           a.CheckpointID.String(),
		BID:           b.CheckpointID.String(),
		ASessions:     a.CheckpointsCount,
		BSessions:     b.CheckpointsCount,
		SessionsDelta: b.CheckpointsCount - a.CheckpointsCount,
	}

	aFiles := make(map[string]struct{}, len(a.FilesTouched))
	for _, f := range a.FilesTouched {
		aFiles[f] = struct{}{}
	}
	bFiles := make(map[string]struct{}, len(b.FilesTouched))
	for _, f := range b.FilesTouched {
		bFiles[f] = struct{}{}
	}
	for f := range bFiles {
		if _, ok := aFiles[f]; !ok {
			out.FilesAdded = append(out.FilesAdded, f)
		}
	}
	for f := range aFiles {
		if _, ok := bFiles[f]; !ok {
			out.FilesRemoved = append(out.FilesRemoved, f)
		}
	}
	sort.Strings(out.FilesAdded)
	sort.Strings(out.FilesRemoved)

	if a.TokenUsage != nil || b.TokenUsage != nil {
		var aIn, aOut, aCR, aCW int
		var bIn, bOut, bCR, bCW int
		if a.TokenUsage != nil {
			aIn = a.TokenUsage.InputTokens
			aOut = a.TokenUsage.OutputTokens
			aCR = a.TokenUsage.CacheReadTokens
			aCW = a.TokenUsage.CacheCreationTokens
		}
		if b.TokenUsage != nil {
			bIn = b.TokenUsage.InputTokens
			bOut = b.TokenUsage.OutputTokens
			bCR = b.TokenUsage.CacheReadTokens
			bCW = b.TokenUsage.CacheCreationTokens
		}
		out.TokensDelta = tokenDelta{
			Total:      (bIn + bOut + bCR + bCW) - (aIn + aOut + aCR + aCW),
